const steps={web:['Choose a small page','Learn semantic HTML','Style with CSS','Make it responsive','Practice JavaScript','Save work with Git','Build a landing page','Connect a public API','Polish two samples','Write a case study'],design:['Learn hierarchy and spacing','Practice typography','Study color and access','Recreate simple layouts','Learn a design tool','Make social posts','Create a flyer','Ask for feedback','Build a concept portfolio','Explain your choices'],video:['Learn editing workflow','Practice pacing','Add readable captions','Balance sound','Learn vertical framing','Edit a short recap','Create a product demo','Export formats','Review sound-off access','Show process'],writing:['Choose audience and goal','Practice clear structure','Research and cite','Write a short guide','Draft a product description','Practice headlines','Edit for clarity','Create samples','Ask feedback','Prepare a portfolio'],seo:['Learn discovery basics','Explore search intent','Practice page titles','Review headings and links','Learn technical basics','Create a content brief','Audit a sample page','Prioritize fixes','Avoid ranking promises','Present sample audit'],marketing:['Define audience and goal','Learn channel basics','Study ethical campaigns','Make a content calendar','Draft a campaign brief','Write social copy','Learn measurement basics','Plan a mock campaign','Check claims and access','Show your plan'],ux:['Learn usability basics','Map a user task','Sketch a flow','Study hierarchy','Create prototype','Plan a usability test','Review feedback','Document decisions','Write case study','Build portfolio'],data:['Learn spreadsheet basics','Clean sample data','Understand data types','Make a clear chart','Ask a data question','Note assumptions','Create report','Build dashboard mockup','Check calculations','Present sample safely'],va:['Practice task organization','Write clear updates','Make research summary','Track in spreadsheet','Write a checklist','Learn account safety','Triage sample inbox','Build fictional tracker','Practice handoff','Show workflow'],social:['Learn formats and access','Define audience','Practice short copy','Plan two weeks','Create post set','Write moderation guide','Learn permission basics','Review sample account','Plan concept campaign','Explain choices']};
function header(){return `<header><a class="brand" href="/" aria-label="SkillLaunchpad home"><img class="brand-logo" src="/assets/skilllaunchpad-logo.svg" alt="SkillLaunchpad"></a><button id="platform-menu" aria-label="Open menu" aria-expanded="false" aria-controls="platform-nav">☰</button><nav id="platform-nav" aria-label="Main navigation"><a href="/">Home</a><a href="/skill-finder.html">Skills</a><a href="/roadmaps.html">Roadmaps</a><a href="/resources.html">Resources</a><a href="/about.html">About</a></nav><div class="platform-nav-extra"><a class="nav-start" href="/skill-finder.html">Get Started <span aria-hidden="true">→</span></a><label class="theme-control"><span>Theme</span><select id="theme-toggle" aria-label="Color theme"><option value="system">Auto</option><option value="light">Light</option><option value="dark">Dark</option></select></label><button id="global-search" type="button" aria-label="Search skills, guides, projects and tools">⌕ <span class="search-word">Search</span></button></div></header>`}function footer(){return `<footer><div class="wrap foot platform-footer"><a class="brand" href="/"><img class="brand-logo" src="/assets/skilllaunchpad-logo.svg" alt="SkillLaunchpad home"></a><span class="footer-tagline">Practical learning for your next step.</span><div><b>Explore</b><a href="/skill-finder.html">Skills</a><a href="/roadmaps.html">Roadmaps</a><a href="/index.html#guides">Guides</a><a href="/projects.html">Projects</a><a href="/tools.html">Tools</a></div><div><b>Build</b><a href="/portfolio-builder.html">Portfolio</a><a href="/case-study-builder.html">Case studies</a><a href="/challenge/30-day.html">30-Day Challenge</a></div><div><b>Company</b><a href="/about.html">About</a><a href="/contact.html">Contact</a><a href="/faq.html">FAQ</a><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a></div></div><div class="wrap copyright">© 2026 SkillLaunchpad · Practical steps, honest expectations.</div></footer>`}
function enhanceGuide(){const article=document.querySelector('main.article');if(!article||article.querySelector('.guide-next'))return;const slug=location.pathname.split('/').pop().replace(/\.html$/,'');const list=[['choose-your-first-digital-skill','Choose your first digital skill'],['first-portfolio-no-experience','Make your first portfolio with no experience'],['portfolio-without-clients','Build a portfolio without client work'],['turn-a-practice-project-into-a-case-study','Turn a practice project into a case study'],['plan-a-small-freelance-project','Plan a small freelance project'],['write-freelance-profile-with-no-experience','Write a freelance profile with no experience'],['first-client-message','Write a first-client message'],['write-first-freelance-proposal','Write a freelance proposal'],['freelance-offer-red-flags','Freelance offer red flags']];const i=list.findIndex(x=>x[0]===slug);if(i<0)return;const prev=i>0?list[i-1]:null,next=i<list.length-1?list[i+1]:null,related=['web','web','web','design','writing','writing','writing','writing','web'][i]||'web';const section=document.createElement('section');section.className='guide-next';section.innerHTML=`<small>KEEP THE LEARNING LOOP GOING</small><h2>What’s next?</h2><p>${next?'Continue with another practical guide, then use its idea in a small project.':'You’ve reached the end of this guide list. Turn one idea into a small practice brief.'}</p><div class="guide-next-actions">${prev?`<a class="secondary" href="${prev[0]}.html">← Previous: ${esc(prev[1])}</a>`:''}${next?`<a class="platform-btn" href="${next[0]}.html">Next guide: ${esc(next[1])} →</a>`:`<a class="platform-btn" href="/projects.html">Explore practice projects →</a>`}<a class="secondary" href="/projects.html">Start a project →</a><a class="secondary" href="/roadmaps.html?skill=${related}">Explore the ${esc(skills.find(s=>s[0]===related)?.[1]||'related')} roadmap →</a></div><button type="button" class="guide-complete" aria-pressed="false">Mark this guide complete</button>`;const cta=article.querySelector('.article-cta');if(cta)cta.insertAdjacentElement('beforebegin',section);else article.append(section);const button=section.querySelector('.guide-complete');let done=read('guides',[]);const update=()=>{done=read('guides',[]);const active=done.includes(slug);button.setAttribute('aria-pressed',String(active));button.textContent=active?'Completed ✓':'Mark this guide complete'};button.addEventListener('click',()=>{done=read('guides',[]);done=done.includes(slug)?done.filter(x=>x!==slug):[...done,slug];save('guides',done);update()});update()}
function common(){let main=document.querySelector('main');if(main&&!main.id)main.id='main-content';if(!document.querySelector('.skip-link')){const skip=document.createElement('a');skip.className='skip-link';skip.href='#'+(main?.id||'main-content');skip.textContent='Skip to content';document.body.prepend(skip)}const nav=$('#platform-nav')||$('#primary-navigation');if(nav){nav.setAttribute('aria-label','Main navigation');if(!document.body.dataset.page&&!/^\/(?:index\.html)?$/.test(location.pathname)){nav.innerHTML='<a href="/">Home</a><a href="/skill-finder.html">Skills</a><a href="/roadmaps.html">Roadmaps</a><a href="/resources.html">Resources</a><a href="/about.html">About</a>';const extra=document.querySelector('.platform-nav-extra');if(extra&&!extra.querySelector('.nav-start'))extra.insertAdjacentHTML('afterbegin','<a class="nav-start" href="/skill-finder.html">Start Here <span aria-hidden="true">→</span></a>')}nav.querySelectorAll('a').forEach(a=>{const href=a.getAttribute('href')||'',target=href.split('#')[0],path=location.pathname.replace(/\/$/,'/index.html');if(target&&((target===path)||(target==='/'&&path==='/index.html')||(path.startsWith('/guides/')&&href.includes('#guides')))){a.setAttribute('aria-current','page')}a.addEventListener('click',()=>{nav.classList.remove('open');$('#platform-menu')?.setAttribute('aria-expanded','false');$('#menu')?.setAttribute('aria-expanded','false')})})}const foot=document.querySelector('footer .foot');if(foot){foot.classList.add('platform-footer');foot.innerHTML='<a class="brand" href="/"><img class="brand-logo" src="/assets/skilllaunchpad-logo.svg" alt="SkillLaunchpad home"></a><span class="footer-tagline">Learn a skill. Build something real. Take your next step.</span><div><b>Explore</b><a href="/skill-finder.html">Skills</a><a href="/roadmaps.html">Roadmaps</a><a href="/index.html#guides">Guides</a><a href="/projects.html">Projects</a><a href="/tools-directory.html">Tools</a></div><div><b>Build</b><a href="/portfolio-builder.html">Portfolio</a><a href="/case-study-builder.html">Case studies</a><a href="/challenge/30-day.html">30-Day Challenge</a></div><div><b>Company</b><a href="/about.html">About</a><a href="/contact.html">Contact</a><a href="/faq.html">FAQ</a><a href="/privacy.html">Privacy</a><a href="/terms.html">Terms</a></div><div class="footer-social" aria-label="Connect with SkillLaunchpad"><a href="/contact.html" aria-label="Contact SkillLaunchpad">✉</a></div>'}enhanceGuide();let t=read('theme','system'),theme=$('#theme-toggle');const apply=()=>{const mode=t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t;document.body.dataset.theme=mode;if(theme)theme.value=t};apply();theme?.addEventListener('change',()=>{t=['system','light','dark'].includes(theme.value)?theme.value:'system';save('theme',t);apply()});try{matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(t==='system')apply()})}catch{}$('#global-search')?.addEventListener('click',search);$('#platform-menu')?.addEventListener('click',e=>{let n=$('#platform-nav'),o=n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(o));e.currentTarget.setAttribute('aria-label',o?'Close menu':'Open menu')})}function shell(title,desc,content){document.title=title+' | SkillLaunchpad';document.body.innerHTML='<a class="skip-link" href="#main-content">Skip to content</a>'+header()+`<main id="main-content" class="platform-main"><div class="platform-head"><div class="eyebrow">SKILLLAUNCHPAD · YOUR NEXT STEP</div><h1>${title}</h1><p>${desc}</p></div>${content}</main>`+footer();common()}
